import{_ as o,a0 as p,w as s,s as d,ao as r,I as a,x as e,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"五個 Linux 下用户空間的調試工具 | LCTT x X-CMD","titleTemplate":false,"description":"五個 Linux 下用户空間的調試工具 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"五個 Linux 下用户空間的調試工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"五個 Linux 下用户空間的調試工具 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20141229 5 User Space Debugging Tools in Linux","title":"五個 Linux 下用户空間的調試工具","tag":"201503","desc":""},"relativePath":"201503/20141229 5 User Space Debugging Tools in Linux.md","filePath":"[post].md"}'),g={name:"201503/20141229 5 User Space Debugging Tools in Linux.md"};function c(u,t,h,m,b,x){const n=p("Link");return s(),d("div",null,[t[19]||(t[19]=r(`<h1 id="五個-linux-下用户空間的調試工具" tabindex="-1">五個 Linux 下用户空間的調試工具 <a class="header-anchor" href="#五個-linux-下用户空間的調試工具" aria-label="Permalink to “五個 Linux 下用户空間的調試工具”">​</a></h1><p>根據定義，調試工具是那些那些使我們能夠監測、控制和糾正其他程序的程序。我們為什麼應該用調試工具呢? 在有些情況下，運行一些程序的時候我們會被卡住，我們需要明白究竟發生了什麼。 例如，我們正在運行應用程序，它產生了一些錯誤消息。要修復這些錯誤，我們應該先找出為什麼產生這些錯誤的消息和這些錯誤消息從哪裏產生的。 一個應用程序可能突然掛起，我們必須瞭解其他什麼進程同時在運行。我們可能還必須弄清楚某個進程掛起的時候在做什麼。為了剖析這些細節， 我們需要調試工具的幫助。</p><p>有幾個Linux下的用户空間調試工具和技術，它們用來分析用户空間的問題相當有用。它們是:</p><ul><li><strong>&#39;print&#39; 語句</strong></li><li><strong>查詢 (/proc, /sys 等)</strong></li><li><strong>跟蹤 (strace/ltrace)</strong></li><li><strong>Valgrind (memwatch)</strong></li><li><strong>GDB</strong></li></ul><p>讓我們一個個地瞭解。</p><h3 id="_1-print-語句" tabindex="-1">1.&#39;print&#39; 語句 <a class="header-anchor" href="#_1-print-語句" aria-label="Permalink to “1.&#39;print&#39; 語句”">​</a></h3><p>這是一個基本的原始的調試問題的方法。 我們可以在程序中插入print語句來了解控制流和變量值。 雖然這是一個簡單的技術， 但它有一些缺點。 程序需要進行編輯以添加&#39;print&#39;語句，然後必須重新編譯，重新運行來獲得輸出。 如果要調試的程序相當大，這是一個耗時的方法。</p><h3 id="_2-查詢" tabindex="-1">2. 查詢 <a class="header-anchor" href="#_2-查詢" aria-label="Permalink to “2. 查詢”">​</a></h3><p>在某些情況下，我們需要弄清楚在一個運行在內核中的進程的狀態和內存映射。為了獲得這些信息，我們不需要在內核中插入任何代碼。 相反，可以用 /proc 文件系統。</p><p>/proc 是一個偽文件系統，系統一啓動運行就收集着運行時系統的信息 (cpu信息, 內存容量等)。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/proc-output.png" alt="output of &#39;ls /proc&#39;"></p><p><em>&#39;ls /proc&#39;的輸出</em></p><p>正如你看到的, 系統中運行的每一個進程在/proc文件系統中有一個以進程id命名的項。每個進程的細節信息可以在進程id對應的目錄下的文件中獲得。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/proc-pid.png" alt="output of &#39;ls /proc/pid&#39;"></p><p><em>&#39;ls /proc/pid&#39;的輸出</em></p><p>解釋/proc文件系統內的所有條目超出了本文的範圍。一些有用的列舉如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- /proc/cmdline -&gt; 內核命令列</span></span>
<span class="line"><span>- /proc/cpuinfo -&gt; 關於處理器的品牌，型號信息等</span></span>
<span class="line"><span>- /proc/filesystems -&gt; 文件系統的內核支持的信息</span></span>
<span class="line"><span>- /proc/&lt;pid&gt;/cmdline -&gt; 命令列參數傳遞到當前進程</span></span>
<span class="line"><span>- /proc/&lt;pid&gt;/mem -&gt; 當前進程持有的內存</span></span>
<span class="line"><span>- /proc/&lt;pid&gt;/status -&gt; 當前進程的狀態</span></span></code></pre></div><h3 id="_3-跟蹤" tabindex="-1">3. 跟蹤 <a class="header-anchor" href="#_3-跟蹤" aria-label="Permalink to “3. 跟蹤”">​</a></h3><p>strace的和ltrace是兩個在Linux中用來追蹤程序的執行細節的跟蹤工具。</p><h4 id="strace" tabindex="-1">strace: <a class="header-anchor" href="#strace" aria-label="Permalink to “strace:”">​</a></h4><p>strace攔截和記錄系統調用及其接收的信號。對於用户，它顯示了系統調用、傳遞給它們的參數和返回值。strace的可以附着到已在運行的進程或一個新的進程。它作為一個針對開發者和系統管理員的診斷、調試工具是很有用的。它也可以用來當做一個通過跟蹤不同的程序調用來了解系統的工具。這個工具的好處是不需要源代碼，程序也不需要重新編譯。</p><p>使用strace的基本語法是：</p><p><strong>strace 命令</strong></p><p>strace有各種各樣的參數。可以檢查看strace的手冊頁來獲得更多的細節。</p><p>strace的輸出非常長，我們通常不會對顯示的每一行都感興趣。我們可以用&#39;-e expr&#39;選項來過濾不想要的數據。</p><p>用 &#39;-p pid&#39; 選項來綁到運行中的進程.</p><p>用&#39;-o&#39;選項，命令的輸出可以被重定向到文件。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/strace-output.png" alt="output of strace filtering only the open system call"></p><p><em>strace過濾成只有系統調用的輸出</em></p><h4 id="ltrace" tabindex="-1">ltrace: <a class="header-anchor" href="#ltrace" aria-label="Permalink to “ltrace:”">​</a></h4><p>ltrace跟蹤和記錄一個進程的動態（運行時）庫的調用及其收到的信號。它也可以跟蹤一個進程所作的系統調用。它的用法是類似與strace。</p><p><strong>ltrace command</strong></p><p>&#39;-i&#39; 選項在調用庫時打印指令指針。</p><p>&#39;-S&#39; 選項被用來現實系統調用和庫調用</p><p>所有可用的選項請參閲ltrace手冊。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/ltrace-output.png" alt="output of ltrace capturing &#39;strcmp&#39; library call"></p><p><em>ltrace捕捉&#39;STRCMP&#39;庫調用的輸出</em></p><h3 id="_4-valgrind" tabindex="-1">4. Valgrind <a class="header-anchor" href="#_4-valgrind" aria-label="Permalink to “4. Valgrind”">​</a></h3><p>Valgrind是一套調試和分析工具。它的一個被廣泛使用的默認工具——&#39;Memcheck&#39;——可以攔截malloc()，new()，free()和delete()調用。換句話説，它在檢測下面這些問題非常有用：</p><ul><li>內存泄露</li><li>重釋放</li><li>訪問越界</li><li>使用未初始化的內存</li><li>使用已經被釋放的內存等。</li></ul><p>它直接通過可執行文件運行。</p><p>Valgrind也有一些缺點，因為它增加了內存佔用，會減慢你的程序。它有時會造成誤報和漏報。它不能檢測出靜態分配的數組的訪問越界問題。</p>`,42)),a("p",null,[t[1]||(t[1]=e("為了使用它，首先請",-1)),l(n,{href:"http://valgrind.org/downloads.html"},{default:i(()=>[...t[0]||(t[0]=[e("下載",-1)])]),_:1}),t[2]||(t[2]=e("並安裝在你的系統上。可以使用操作系統上的包管理器來安裝。",-1))]),t[20]||(t[20]=r(`<p>使用命令列安裝需要解壓縮和解包下載的文件。</p><pre><code>tar -xjvf valgring-x.y.z.tar.bz2 (where x.y.z is the version number you are trying to install)
</code></pre><p>進入新創建的目錄（的valgrind-XYZ）內運行以下命令：</p><pre><code>./configure
make
make install
</code></pre><p>讓我們通過一個小程序(test.c)來理解valgrind怎麼工作的:</p><pre><code>#include &lt;stdio.h&gt;

void f(void)

{
int x = malloc(10 * sizeof(int));

x[10] = 0;
}

int main()
{
f();
return 0;
}
</code></pre><p>編譯程序:</p><pre><code>gcc -o test -g test.c
</code></pre><p>現在我們有一個可執行文件叫做&#39;test&#39;。我們現在可以用valgrind來檢測內存錯誤：</p><pre><code>valgrind –tool=memcheck –leak-check=yes test
</code></pre><p>這是valgrind呈現錯誤的輸出：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/Valgrind.png" alt="output of valgrind showing heap block overrun and memory leak"></p><p><em>valgrind顯示堆溢出和內存泄漏的輸出</em></p><p>正如我們在上面看到的消息，我們正在試圖訪問函數f未分配的內存以及分配尚未釋放的內存。</p><h3 id="_5-gdb" tabindex="-1">5. GDB <a class="header-anchor" href="#_5-gdb" aria-label="Permalink to “5. GDB”">​</a></h3><p>GDB是來自自由軟件基金會的調試器。它對定位和修復代碼中的問題很有幫助。當被調試的程序運行時，它給用户控制權去執行各種動作， 比如:</p><ul><li>啓動程序</li><li>停在指定位置</li><li>停在指定的條件</li><li>檢查所需信息</li><li>改變程序中的數據 等。</li></ul><p>你也可以將一個崩潰的程序coredump附着到GDB並分析故障的原因。</p><p>GDB提供很多選項來調試程序。 然而，我們將介紹一些重要的選擇，來感受如何開始使用GDB。</p>`,19)),a("p",null,[t[4]||(t[4]=e("如果你還沒有安裝GDB，可以在這裏下載：",-1)),l(n,{href:"http://www.gnu.org/software/gdb/download/"},{default:i(()=>[...t[3]||(t[3]=[e("GDB官方網站",-1)])]),_:1}),t[5]||(t[5]=e("。",-1))]),t[21]||(t[21]=r(`<h4 id="編譯程序" tabindex="-1">編譯程序: <a class="header-anchor" href="#編譯程序" aria-label="Permalink to “編譯程序:”">​</a></h4><p>為了用GDB調試程序，必須使用gcc的&#39;-g&#39;選項進行編譯。這將以操作系統的本地格式產生調試信息，GDB利用這些信息來工作。</p><p>下面是一個簡單的程序（example1.c）執行被零除用來顯示GDB的用法:</p><pre><code>#include
int divide()
{
int x=5, y=0;
return x / y;
}

int main()
{
divide();
}
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gdb-example.png" alt="An example showing usage of gdb"></p><p><em>展示GDB用法的例子</em></p><h4 id="調用-gdb" tabindex="-1">調用 GDB: <a class="header-anchor" href="#調用-gdb" aria-label="Permalink to “調用 GDB:”">​</a></h4><p>通過在命令列中執行&#39;gdb&#39;來啓動gdb:</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gdb.png" alt="invoking gdb"></p><p><em>調用 gdb</em></p><p>調用後, 它將等待終端命令並執行，直到退出。</p><p>如果一個進程已經在運行，你需要將GDB連接到它上面，可以通過指定進程ID來實現。假設程序已經崩潰，要分析問題的原因，則用GDB分析core文件。</p><h4 id="啓動程序" tabindex="-1">啓動程序: <a class="header-anchor" href="#啓動程序" aria-label="Permalink to “啓動程序:”">​</a></h4><p>一旦你在GDB裏面，使用&#39;run&#39;命令來啓動程序進行調試。</p><h4 id="給程序傳參數" tabindex="-1">給程序傳參數: <a class="header-anchor" href="#給程序傳參數" aria-label="Permalink to “給程序傳參數:”">​</a></h4><p>使用&#39;set args&#39;給你的程序傳參數，當程序下次運行時將獲得該參數。&#39;show args&#39;將顯示傳遞給程序的參數。</p><h4 id="檢查堆棧" tabindex="-1">檢查堆棧: <a class="header-anchor" href="#檢查堆棧" aria-label="Permalink to “檢查堆棧:”">​</a></h4><p>每當程序停止，任何人想明白的第一件事就是它為什麼停止，以及怎麼停在那裏的。該信息被稱為反向跟蹤。由程序產生每個函數調用和局部變量，傳遞的參數，調用位置等信息一起存儲在堆棧內的數據塊種，被稱為一幀。我們可以使用GDB來檢查所有這些數據。 GDB從最底層的幀開始給這些幀編號。</p><ul><li><strong>bt</strong>: 打印整個堆棧的回溯</li><li><strong>bt <code>&lt;n&gt;</code></strong> 打印n個幀的回溯</li><li><strong>frame <code>&lt;frame number&gt;</code></strong>: 切換到指定的幀，並打印該幀</li><li><strong>up <code>&lt;n&gt;</code></strong>: 上移&#39;n&#39;個幀</li><li><strong>down <code>&lt;n&gt;</code></strong>: 下移&#39;n&#39;個幀 ( n默認是1)</li></ul><h4 id="檢查數據" tabindex="-1">檢查數據: <a class="header-anchor" href="#檢查數據" aria-label="Permalink to “檢查數據:”">​</a></h4><p>程序的數據可以在裏面GDB使用&#39;print&#39;命令進行檢查。例如，如果&#39;x&#39;是調試程序內的變量，&#39;print x&#39;會打印x的值。</p><h4 id="檢查源碼" tabindex="-1">檢查源碼: <a class="header-anchor" href="#檢查源碼" aria-label="Permalink to “檢查源碼:”">​</a></h4><p>源碼可以在GDB中打印。默認情況下，&#39;list&#39;命令會打印10行代碼。</p><ul><li><strong>list <code>&lt;linenum&gt;</code></strong>: 列出&#39;linenum&#39;行周圍的源碼</li><li><strong>list <code>&lt;function&gt;</code></strong>: 從&#39;function&#39;開始列出源碼</li><li><strong>disas <code>&lt;function&gt;</code></strong>: 顯示該函數機器代碼</li></ul><h4 id="停止和恢復程序" tabindex="-1">停止和恢復程序: <a class="header-anchor" href="#停止和恢復程序" aria-label="Permalink to “停止和恢復程序:”">​</a></h4><p>使用GDB，我們可以在必要的地方設置斷點，觀察點等來停止程序。</p><ul><li><strong>break <code>&lt;location&gt;</code></strong>: 在&#39;location&#39;設置一個斷點。當在程序執行到這裏時斷點將被擊中，控制權被交給用户。</li><li><strong>watch <code>&lt;expr&gt;</code></strong>: 當&#39;expr&#39;被程序寫入而且它的值發生變化時GDB將停止</li><li><strong>catch <code>&lt;event&gt;</code></strong>: 當&#39;event&#39;發生時GDB停止</li><li><strong>disable <code>&lt;breakpoint&gt;</code></strong>: 禁用指定斷點</li><li><strong>enable <code>&lt;breakpoint&gt;</code></strong>: 啓用指定斷點</li><li><strong>delete <code>&lt;breakpoint&gt;</code></strong>: 刪除 斷點/觀察點/捕獲點。 如果沒有傳遞參數默認操作是在所有的斷點</li><li><strong>step</strong>: 一步一步執行程序</li><li><strong>continue</strong>: 繼續執行程序，直到執行完畢</li></ul><h4 id="退出-gdb" tabindex="-1">退出 GDB: <a class="header-anchor" href="#退出-gdb" aria-label="Permalink to “退出 GDB:”">​</a></h4><p>用&#39;quit&#39;命令還從GDB中退出。</p><p>GDB還有更多的可用選項。裏面GDB使用help選項瞭解更多詳情。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gdb-help.png" alt="getting help within gdb"></p><p><em>在GDB中獲得幫助</em></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在這篇文章中，我們已經看到不同類型的Linux用户空間的調試工具。總結以上所有內容，如下是什麼時候使用該什麼的快速指南：</p><ul><li>基本調試，獲得關鍵變量 - print 語句</li><li>獲取有關文件系統支持，可用內存，CPU，運行程序的內核狀態等信息 - 查詢 /proc 文件系統</li><li>最初的問題診斷，系統調用或庫調用的相關問題，瞭解程序流程 – strace / ltrace</li><li>應用程序內存空間的問題 – valgrind</li><li>檢查應用程序運行時的行為，分析應用程序崩潰 – gdb</li></ul><hr>`,36)),a("p",null,[t[7]||(t[7]=e("via: ",-1)),l(n,{href:"http://linoxide.com/linux-how-to/user-space-debugging-tools-linux/"},{default:i(()=>[...t[6]||(t[6]=[e("http://linoxide.com/linux-how-to/user-space-debugging-tools-linux/",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=e("作者：",-1)),l(n,{href:"http://linoxide.com/author/bnpoornima/"},{default:i(()=>[...t[8]||(t[8]=[e("B N Poornima",-1)])]),_:1}),t[12]||(t[12]=e(" 譯者：",-1)),l(n,{href:"https://github.com/mtunique"},{default:i(()=>[...t[9]||(t[9]=[e("mtunique",-1)])]),_:1}),t[13]||(t[13]=e(" 校對：",-1)),l(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[16]||(t[16]=e("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原創翻譯，",-1)),l(n,{href:"http://linux.cn/"},{default:i(()=>[...t[15]||(t[15]=[e("Linux中國",-1)])]),_:1}),t[18]||(t[18]=e(" 榮譽推出",-1))])])}const T=o(g,[["render",c]]);export{D as __pageData,T as default};
